export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeUrl(value,image=false){if(image&&/^data:image\/(png|jpeg|webp|gif);base64,[a-z0-9+/=]+$/i.test(value))return value;try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
const commandWords=new Set('nmap curl python python3 ssh strings grep cat ls touch id whoami printf echo sleep systemctl'.split(' '));
const sqlWords=new Set('select from where show databases tables describe table version as order by limit format insert into values settings'.split(' '));
function highlight(source,language=''){
 const token=/#[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\$\{?[A-Za-z_]\w*\}?|--[A-Za-z][\w-]*|\b[A-Za-z_][\w-]*\b|\b\d+(?:\.\d+){0,3}\b/g;
 let out='',last=0,match;
 while((match=token.exec(source))){out+=escape(source.slice(last,match.index));const word=match[0],lower=word.toLowerCase();let kind='';
  if(word.startsWith('#'))kind='comment';else if(word[0]==='"'||word[0]==="'")kind='string';else if(word[0]==='$')kind='variable';else if(word.startsWith('--'))kind='option';else if(sqlWords.has(lower))kind='keyword';else if(commandWords.has(lower))kind='command';else if(/^\d/.test(word))kind='number';
  out+=kind?`<span class="tok-${kind}">${escape(word)}</span>`:escape(word);last=token.lastIndex;
 }
 out+=escape(source.slice(last));return `<pre class="terminal"><code${language?` class="language-${escape(language)}"`:''}>${out}</code></pre>`;
}
function inline(raw){const tokens=[],slot=html=>`\u0000${tokens.push(html)-1}\u0000`;let s=raw.replace(/\u0000/g,'').replace(/`([^`]+)`/g,(_,s)=>slot(`<code>${escape(s)}</code>`));s=s.replace(/!\[([^\]]*)\]\(([^\s)]+)\)/g,(_,alt,url)=>{const safe=safeUrl(url,true);return slot(safe?`<img loading="lazy" src="${escape(safe)}" alt="${escape(alt)}">`:escape(alt));});s=s.replace(/\[([^\]]+)\]\(([^\s)]+)\)/g,(_,label,url)=>{const safe=safeUrl(url);return slot(safe?`<a href="${escape(safe)}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`:escape(label));});s=escape(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');return s.replace(/\u0000(\d+)\u0000/g,(_,i)=>tokens[Number(i)]||'');}
export function markdown(raw){const lines=String(raw||'').replace(/\r\n/g,'\n').split('\n');let out='',paragraph=[],code=null,codeLang='',list=null;const flush=()=>{if(paragraph.length){out+=`<p>${paragraph.map(inline).join('<br>')}</p>`;paragraph=[];}if(list){out+=`</${list}>`;list=null;}};for(const line of lines){if(line.startsWith('```')){flush();if(code!==null){out+=highlight(code.join('\n'),codeLang);code=null;codeLang='';}else{code=[];codeLang=(line.match(/^```([a-z0-9_+-]*)/i)||[])[1]||'';}continue;}if(code!==null){code.push(line);continue;}const heading=line.match(/^(#{1,3})\s+(.+)$/),item=line.match(/^\s*(?:([-*])|\d+\.)\s+(.+)$/);if(!line.trim()){flush();continue;}if(heading){flush();const n=Math.max(2,heading[1].length);out+=`<h${n}>${inline(heading[2])}</h${n}>`;}else if(item){if(paragraph.length)flush();const kind=item[1]?'ul':'ol';if(list!==kind){flush();out+=`<${kind}>`;list=kind;}out+=`<li>${inline(item[2])}</li>`;}else if(line.startsWith('> ')){flush();out+=`<blockquote>${inline(line.slice(2))}</blockquote>`;}else{if(list)flush();paragraph.push(line);}}flush();if(code!==null)out+=highlight(code.join('\n'),codeLang);return out;}
